SELECT count() AS mismatches FROM (SELECT owner_key,field_name,value,author_key,doc_id,version,sum(weight) AS delta FROM (SELECT owner_key,field_name,value,author_key,doc_id,version,toInt8(1) AS weight FROM (SELECT * FROM strings WHERE field_name='tag:node_ad') UNION ALL SELECT owner_key,field_name,value,author_key,doc_id,version,toInt8(-1) AS weight FROM (SELECT 'api.localhost/groups/web10/discover' AS owner_key,'tag:node_ad' AS field_name,doc_id AS value,author_key,doc_id,updated_at AS version FROM documents FINAL WHERE deleted=0 AND has(tags,'node_ad') AND doc_id IN (SELECT doc_id FROM doc_groups FINAL WHERE deleted=0 AND group_id='api.localhost/groups/web10/discover'))) GROUP BY owner_key,field_name,value,author_key,doc_id,version HAVING delta!=0)
